file.content:
        # binds height, parent and Merkle root), so it carries nothing new.
        if any(tip_hash == block.block_hash for block in self.store.chain):
            return 409, {"error": "fork is identical to the canonical chain"}
        if tip_hash in self.store.forks:
            return 409, {"error": "candidate fork already exists", "tip_hash": tip_hash}
        self.store.forks[tip_hash] = fork
        try:
            self.store.save()
        except BaseException:
            self.store.forks.pop(tip_hash, None)
            raise
    return 201, self._fork_summary(fork)

def get_chain(self) -> tuple[int, dict]:
    """GET /v1/chain — canonical chain, candidates sorted by tip hash and
    the adoptable winner (a non-canonical chain that beats canonical).
    """
    with self.store.lock:
        self._prune_expired_syncs()
        canonical = self._fork_summary(self.store.chain)
        candidates = [
            self._fork_summary(self.store.forks[tip])
            for tip in sorted(self.store.forks)
        ]
        winner_tip, winner_chain = self._winning_fork()
        adoptable: list[dict] = []
        if winner_tip != self.store.tip_hash():
            adoptable.append(self._fork_summary(winner_chain))
        return 200, {
            "canonical": canonical,
            "candidates": candidates,
            "adoptable": adoptable,
        }

def adopt_fork(self, tip_hash: object) -> tuple[int, dict]:
    """POST /v1/forks/{tip_hash}/adopt — atomically switch to the winner.

    Unknown tips return 404; adopting anything other than the current
    winning (longest / smallest-tip-hash) chain returns 409. Adoption
    replaces the canonical chain and mempool in one atomic write that
    advances the generation and rebuilds all indexes; transactions unique
    to the old chain's confirmed history return to the mempool, while
    pending-block transactions never enter it.
    """
    if not crypto.is_hex64(tip_hash):
        return 404, {"error": "unknown fork tip"}
    with self.store.lock:
        self._prune_expired_syncs()
        fork = self.store.forks.get(tip_hash)
        if fork is None:
            return 404, {"error": "unknown fork tip"}
        winner_tip, _ = self._winning_fork()
        if winner_tip != tip_hash:
            return 409, {"error": "only the winning fork can be adopted"}
        old_chain = self.store.chain
        old_pending = dict(self.store.pending)
        self.store.forks.pop(tip_hash)
        self.store.replace_chain(fork)
        # An adopted synced tip keeps its sync records (queryable until
        # expiry); record the adoption once per provenance entry. The
        # adopted tip summary is frozen from the adopted fork itself and
        # is never rewritten by later expiry.
        adopted_summary = self._fork_summary(fork)
        # The adopted tip may have provenance entries in the plain table,
        # the attested table, or both; each gets one adoption event.
        adopted: list[tuple[str | None, tuple[str, str]]] = []
        for skey in sorted(self.store.syncs):
            if self.store.syncs[skey]["tip_hash"] == tip_hash:
                adopted.append((None, skey))
        for skey in sorted(self.store.attested_syncs):
            if self.store.attested_syncs[skey]["tip_hash"] == tip_hash:
                adopted.append((SYNC_MODE_ATTESTED, skey))
        adopted_count = len(adopted)
        for rec_mode, (rec_source, request_id) in adopted:
            table = (
                self.store.attested_syncs
                if rec_mode is not None
                else self.store.syncs
            )
            payload = {
                "source": rec_source,
                "request_id": request_id,
                "tip_hash": tip_hash,
                "expires_at": table[(rec_source, request_id)]["expires_at"],
                "height": adopted_summary["height"],
                "length": adopted_summary["length"],
                "status": adopted_summary["status"],
            }
            if rec_mode is not None:
                payload["mode"] = rec_mode
            self.store.append_audit_event(EVENT_SYNC_ADOPTED, payload)
        try:
            self.store.save()
        except BaseException:
            # Restore the pre-adoption in-memory state on a failed write.
            self.store.chain = old_chain
            self.store.pending = old_pending
            self.store.forks[tip_hash] = fork
            self.store.rebuild_derived()
            self.store.truncate_audit_events(adopted_count)
            raise
        return 200, self._fork_summary(fork)

def export_fork(self, tip_hash: object) -> tuple[int, dict]:
    """GET /v1/forks/{tip_hash}/export — full export of a candidate fork.

    Only stored candidates are exportable: the canonical tip, an unknown
    tip and a malformed tip hash (not 64 lowercase hex chars) all return
    404. The response carries exactly five fields — the fork descriptor
    (tip_hash, height, length, status, all describing the tip block) plus
    the full block list including the genesis block, every transaction's
    signature and an optional pending tip — and can be resubmitted to
    POST /v1/forks/candidates verbatim.
    """
    if not crypto.is_hex64(tip_hash):
        return 404, {"error": "unknown fork tip"}
    with self.store.lock:
        fork = self.store.forks.get(tip_hash)
        if fork is None:
            return 404, {"error": "unknown fork tip"}
        body = self._fork_summary(fork)
        body["blocks"] = [block.to_dict() for block in fork]
        return 200, body

# -- incremental chain ranges --------------------------------------------

RANGE_DEFAULT_LIMIT = 100
RANGE_MAX_LIMIT = 500

@staticmethod
def _anchor_descriptor(block: Block) -> dict:
    """Public range anchor shape: {height, block_hash}."""
    return {"height": block.height, "block_hash": block.block_hash}

def get_chain_range(self, params: dict) -> tuple[int, dict]:
    """GET /v1/chain/range — the canonical blocks strictly after an anchor.

    Query parameters: ``after_height`` (a non-negative decimal anchor
    height) and ``after_hash`` (the anchor block's hash, 64 lowercase hex
    characters), both required, plus ``limit`` (default 100, range 1-500).
    Every value must follow the strict decimal/hex format used by the
    other query endpoints; a repeated parameter is rejected by the HTTP
    layer.

    Returns, under the store lock,
    ``{anchor, blocks, canonical, next_height}``: ``anchor`` is
    ``{height, block_hash}`` naming the block the page starts *after*;
    ``blocks`` are the complete blocks following it (full documents
    including transactions; a pending tip block is exported too), up to
    ``limit``; ``canonical`` is the current chain descriptor S;
    ``next_height`` is the height immediately after the returned page, or
    ``null`` when the page already ends at the chain tip. A well-formed
    but unknown anchor height returns 404; a malformed anchor hash returns
    400; an anchor hash that does not match the block at that height
    returns 409.
    """
    after_height_raw = params.get("after_height")
    after_hash = params.get("after_hash")
    if after_height_raw is None:
        return 400, {"error": "missing parameter: after_height"}
    if after_hash is None:
        return 400, {"error": "missing parameter: after_hash"}
    after_height = _parse_decimal(after_height_raw)
    if after_height is None:
        return 400, {"error": "after_height must be a non-negative decimal"}
    if not crypto.is_hex64(after_hash):
        return 400, {"error": "after_hash must be 64 lowercase hex characters"}
    limit = self.RANGE_DEFAULT_LIMIT
    if params.get("limit") is not None:
        parsed = _parse_decimal(params["limit"])
        if parsed is None or not 1 <= parsed <= self.RANGE_MAX_LIMIT:
            return 400, {"error": "limit must be a decimal between 1 and 500"}
        limit = parsed

    with self.store.lock:
        anchor_block = self.store.block_at(after_height)
        if anchor_block is None:
            return 404, {"error": "anchor block not found"}
        if after_hash is not None and after_hash != anchor_block.block_hash:
            return 409, {
                "error": "after_hash does not match the block at after_height"
            }
        page = self.store.chain[
            after_height + 1 : after_height + 1 + limit
        ]
        page_end_height = page[-1].height if page else anchor_block.height
        if page_end_height < self.store.chain[-1].height:
            next_height = page_end_height + 1
        else:
            next_height = None
        return 200, {
            "anchor": self._anchor_descriptor(anchor_block),
            "blocks": [block.to_dict() for block in page],
            "canonical": self._fork_summary(self.store.chain),
            "next_height": next_height,
        }

# -- signed block-header pages -------------------------------------------

@staticmethod
def _header_entry(block: Block) -> dict:
    """One signed header page item in its fixed key order."""
    return {
        "height": block.height,
        "prev_hash": block.prev_hash,
        "merkle_root": block.merkle_root,
        "block_hash": block.block_hash,
        "status": block.status,
    }

def get_chain_headers(self, params: dict) -> tuple[int, dict]:
    """GET /v1/chain/headers — one signed page of block headers.

    Query parameters follow exactly the same rules as
    ``GET /v1/chain/range``: ``after_height`` and ``after_hash`` are both
    required, ``limit`` defaults to 100 and must be a decimal between 1
    and 500; malformed values or unknown parameters are 400, an unknown
    anchor height is 404 and an anchor hash mismatch is 409.

    The success body has the fixed key order ``anchor, headers, tip,
    auth``: ``anchor`` is ``{height, block_hash}`` (the block the page
    starts *after*), ``headers`` are the headers strictly after it in
    ascending height with item key order
    ``height, prev_hash, merkle_root, block_hash, status`` (no
    transactions; a pending chain tip is exported as the page tail),
    ``tip`` is the current chain descriptor S, and ``auth`` is
    ``{key_version, signature}`` — an Ed25519 signature made with the
    current audit signer over
    ``SHA256(UTF8("ledger-headers-v1") || canonical_json({anchor, headers,
    tip}))``. When the anchor is the current tip the page carries an
    empty ``headers`` list, still signed.
    """
    after_height_raw = params.get("after_height")
    after_hash = params.get("after_hash")
    if after_height_raw is None:
        return 400, {"error": "missing parameter: after_height"}
    if after_hash is None:
        return 400, {"error": "missing parameter: after_hash"}
    after_height = _parse_decimal(after_height_raw)
    if after_height is None:
        return 400, {"error": "after_height must be a non-negative decimal"}
    if not crypto.is_hex64(after_hash):
        return 400, {"error": "after_hash must be 64 lowercase hex characters"}
    limit = self.RANGE_DEFAULT_LIMIT
    if params.get("limit") is not None:
        parsed = _parse_decimal(params["limit"])
        if parsed is None or not 1 <= parsed <= self.RANGE_MAX_LIMIT:
            return 400, {"error": "limit must be a decimal between 1 and 500"}
        limit = parsed

    from . import light_client

    with self.store.lock:
        anchor_block = self.store.block_at(after_height)
        if anchor_block is None:
            return 404, {"error": "anchor block not found"}
        if after_hash != anchor_block.block_hash:
            return 409, {
                "error": "after_hash does not match the block at after_height"
            }
        page = self.store.chain[
            after_height + 1 : after_height + 1 + limit
        ]
        anchor = self._anchor_descriptor(anchor_block)
        headers = [self._header_entry(block) for block in page]
        tip = self._fork_summary(self.store.chain)
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot (including migrated legacy ones) carries a
            # current audit signer after recovery; reaching here is a
            # programming error rather than a client-visible condition.
            raise RuntimeError("no audit signer available for header page")
        auth = light_client.sign_header_page(
            signer["private_key"], signer["version"], anchor, headers, tip
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        return 200, {
            "anchor": anchor,
            "headers": headers,
            "tip": tip,
            "auth": auth,
        }

def locate_header_fork(self, payload: object) -> tuple[int, dict]:
    """POST /v1/chain/headers/locate — fork location by block locators.

    The request body is a JSON object with the ordered keys ``locators``
    and the optional ``limit``: ``locators`` is an array of 1-64
    ``{height, block_hash}`` items (item key order ``height, block_hash``),
    each height a non-boolean non-negative integer, strictly descending
    and unique across the array, and each hash 64 lowercase hexadecimal
    characters; ``limit`` is a non-boolean integer between 1 and 500 and
    defaults to 100. Every parse or key/value defect is a 400 answered
    before any state is read (no side effects).

    The locators are probed in their supplied order and the first item at
    the same height with the same hash as a main-chain block anchors the
    response; when no locator names a main-chain block the answer is 409.
    On success the body is the same fixed-order signed header page as
    :meth:`get_chain_headers` — ``anchor, headers, tip, auth`` — with the
    headers ascending strictly after the matched anchor (at most
    ``limit`` items; an empty page is signed when the anchor is the tip).
    The main chain and the audit signer are snapshotted together under one
    store lock so the descriptor, the page and the signature can never mix
    states.
    """
    if not isinstance(payload, dict):
        return 400, {"error": "request body must be a JSON object"}
    keys = tuple(payload.keys())
    if keys not in (("locators",), ("locators", "limit")):
        return 400, {
            "error": "body must contain only ordered keys locators, limit"
        }
    raw_locators = payload["locators"]
    if not isinstance(raw_locators, list) or not (
        1 <= len(raw_locators) <= 64
    ):
        return 400, {
            "error": "field 'locators' must be an array of 1 to 64 items"
        }
    locators: list[dict] = []
    previous_height: int | None = None
    for item in raw_locators:
        if not isinstance(item, dict) or tuple(item.keys()) != (
            "height",
            "block_hash",
        ):
            return 400, {
                "error": "every locator must be an object with ordered "
                "keys height, block_hash"
            }
        height = item["height"]
        block_hash = item["block_hash"]
        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            return 400, {
                "error": "locator height must be a non-negative integer"
            }
        if not crypto.is_hex64(block_hash):
            return 400, {
                "error": "locator block_hash must be 64 lowercase hex characters"
            }
        if previous_height is not None and height >= previous_height:
            return 400, {
                "error": "locator heights must be strictly descending and unique"
            }
        previous_height = height
        locators.append({"height": height, "block_hash": block_hash})
    limit = self.RANGE_DEFAULT_LIMIT
    if "limit" in payload:
        raw_limit = payload["limit"]
        if (
            isinstance(raw_limit, bool)
            or not isinstance(raw_limit, int)
            or not 1 <= raw_limit <= self.RANGE_MAX_LIMIT
        ):
            return 400, {"error": "limit must be an integer between 1 and 500"}
        limit = raw_limit

    from . import light_client

    with self.store.lock:
        anchor_block = None
        for locator in locators:
            candidate = self.store.block_at(locator["height"])
            if (
                candidate is not None
                and candidate.block_hash == locator["block_hash"]
            ):
                anchor_block = candidate
                break
        if anchor_block is None:
            return 409, {"error": "no locator matches a main-chain block"}
        anchor_height = anchor_block.height
        page = self.store.chain[
            anchor_height + 1 : anchor_height + 1 + limit
        ]
        anchor = self._anchor_descriptor(anchor_block)
        headers = [self._header_entry(block) for block in page]
        tip = self._fork_summary(self.store.chain)
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot carries a current audit signer after
            # recovery; reaching here is a programming error.
            raise RuntimeError("no audit signer available for header page")
        auth = light_client.sign_header_page(
            signer["private_key"], signer["version"], anchor, headers, tip
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        return 200, {
            "anchor": anchor,
            "headers": headers,
            "tip": tip,
            "auth": auth,
        }

# -- inter-node fork sync -------------------------------------------------

SYNC_DEFAULT_LIMIT = 50
SYNC_MAX_LIMIT = 200

@staticmethod
def _candidate_blocks(candidate: object) -> object:
    """Normalize a sync ``candidate`` to its raw blocks list.

    The candidate follows the existing export format (the five-field
    ``{tip_hash, height, length, status, blocks}`` document); the
    ``{"blocks": [...]}`` wrapper and a bare block list are accepted too.
    """
    if isinstance(candidate, dict):
        return candidate.get("blocks")
    return candidate

@staticmethod
def _candidate_fingerprint(blocks_raw: list) -> str:
    """Stable content fingerprint of a candidate's raw block list.

    Used to decide whether a same-key retry carries the same candidate
    content. Key order and whitespace are normalized so two documents that

    "finalized",
    "steps",
    "hash",
)

# The exact key order of one stored step, per format version: version-1
# steps carry only the linear-batch fields, version-2 steps add the step
# kind and the locator request a reorg batch was verified against.
HEADER_STEP_KEYS = ("tip_hash", "trust", "documents")
HEADER_STEP_V2_KEYS = ("kind", "tip_hash", "trust", "documents", "locators")

# The stored step kinds: ``linear`` (an advance_headers batch, locators
# null) and ``locator`` (a reorg_headers batch carrying its locators).
HEADER_STEP_KINDS = ("linear", "locator")

# The header checkpoint format versions: version-1 and version-2 files are
# still read (their steps replay as linear/locator and their anchor is
# taken as the finalized boundary); everything written is version 3.
HEADER_CHECKPOINT_VERSION = 3
HEADER_CHECKPOINT_VERSIONS = (1, 2, HEADER_CHECKPOINT_VERSION)

# Fixed success key order returned by :func:`advance_headers`.
ADVANCE_HEADERS_RESULT_KEYS = ("ok", "generation", "tip")

# Fixed success key order returned by :func:`reorg_headers`.
REORG_HEADERS_RESULT_KEYS = ("ok", "generation", "tip", "replaced")

# Fixed success key order returned by :func:`finalize_headers`.
FINALIZE_HEADERS_RESULT_KEYS = ("ok", "generation", "finalized")


def _header_checkpoint_body(
    v: int,
    generation: int,
    anchor: dict,
    tip: dict,
    finalized: dict,
    steps: list,
) -> dict:
    """The hash-covered checkpoint body in its stored per-version form.

    Steps are normalized to the version-2+ shape internally; a version-1
    body projects them back to the legacy three-key shape so a legacy
    file's recorded digest still recomputes. The ``finalized`` boundary is
    a version-3 field only; version 2 carries the same steps but no
    boundary, so its recorded digest recomputes too.
    """
    step_keys = HEADER_STEP_KEYS if v == 1 else HEADER_STEP_V2_KEYS
    body = {
        "v": v,
        "generation": generation,
        "anchor": anchor,
        "tip": tip,
        "steps": [{key: step[key] for key in step_keys} for step in steps],
    }
    if v >= HEADER_CHECKPOINT_VERSION:
        body["finalized"] = finalized
    return body


def _header_checkpoint_hash(
    v: int,
    generation: int,
    anchor: dict,
    tip: dict,
    finalized: dict,
    steps: list,
) -> str:
    """SHA-256 over the canonical JSON bytes of every field but ``hash``."""
    return hashlib.sha256(
        _canonical_json_bytes(
            _header_checkpoint_body(
                v, generation, anchor, tip, finalized, steps
            )
        )
    ).hexdigest()


def _header_tip_advances(stored: dict, new: dict) -> bool:
    """Whether ``new`` is a legal successor tip of ``stored``.

    The tip may never drop in height; at the same height only the same
    ``block_hash`` moving from ``pending`` to ``confirmed`` is accepted.
    """
    if new["height"] != stored["height"]:
        return new["height"] > stored["height"]
    return (
        new["tip_hash"] == stored["tip_hash"]
        and stored["status"] == STATUS_PENDING
        and new["status"] == STATUS_CONFIRMED
    )


def _header_tip_reorgs(stored: dict, new: dict) -> bool:
    """Whether ``new`` is a legal reorg successor tip of ``stored``.

    The tip may never drop in height; at the same height a different
    ``block_hash`` — the reorganization itself — is accepted in either
    status, while the same hash may only move from ``pending`` to
    ``confirmed``. Anything else at the same height is a conflict.
    """
    if new["height"] != stored["height"]:
        return new["height"] > stored["height"]
    if new["tip_hash"] != stored["tip_hash"]:
        return True
    return (
        stored["status"] == STATUS_PENDING
        and new["status"] == STATUS_CONFIRMED
    )


def _validate_header_checkpoint_shape(data: object) -> dict:
    """Validate the exact key order and JSON types of one checkpoint document.

    Version-3 files carry the full key order
    ``v, generation, anchor, tip, finalized, steps, hash``; version-1 and
    version-2 files carry the legacy order without ``finalized`` and read
    with the boundary equal to the anchor.
    """
    if not isinstance(data, dict):
        raise _CheckpointError(ERR_STATE)
    if not _is_int(data.get("v")):
        raise _CheckpointError(ERR_STATE)
    if data["v"] == HEADER_CHECKPOINT_VERSION:
        # Version 3 requires the full key order including finalized.
        if tuple(data.keys()) != HEADER_CHECKPOINT_KEYS:
            raise _CheckpointError(ERR_STATE)
    elif data["v"] in (1, 2):
        if tuple(data.keys()) != (
            "v",
            "generation",
            "anchor",
            "tip",
            "steps",
            "hash",
        ):
            raise _CheckpointError(ERR_STATE)
    else:
        raise _CheckpointError(ERR_STATE)
    v = data["v"]
    generation = data["generation"]
    anchor = data["anchor"]
    tip = data["tip"]
    steps = data["steps"]
    digest = data["hash"]

    if not _is_int(v) or v not in HEADER_CHECKPOINT_VERSIONS:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(generation) or generation < 1:
        raise _CheckpointError(ERR_STATE)
    if not isinstance(anchor, dict) or tuple(anchor.keys()) != HEADER_ANCHOR_KEYS:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(anchor["height"]) or anchor["height"] < 0:
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(anchor["block_hash"]):
        raise _CheckpointError(ERR_STATE)
    if not isinstance(tip, dict) or tuple(tip.keys()) != HEADER_TIP_KEYS:
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(tip["tip_hash"]):
        raise _CheckpointError(ERR_STATE)
    if not _is_int(tip["height"]) or tip["height"] < 0:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(tip["length"]) or tip["length"] < 1:
        raise _CheckpointError(ERR_STATE)
    if tip["status"] not in (STATUS_PENDING, STATUS_CONFIRMED):
        raise _CheckpointError(ERR_STATE)
    # Version 3 pins the finalized boundary explicitly; legacy versions
    # take the initial anchor as the boundary.
    if v == HEADER_CHECKPOINT_VERSION:
        finalized_raw = data["finalized"]
        if (
            not isinstance(finalized_raw, dict)
            or tuple(finalized_raw.keys()) != HEADER_ANCHOR_KEYS
        ):
            raise _CheckpointError(ERR_STATE)
        if not _is_int(finalized_raw["height"]) or finalized_raw["height"] < 0:
            raise _CheckpointError(ERR_STATE)
        if not crypto.is_hex64(finalized_raw["block_hash"]):
            raise _CheckpointError(ERR_STATE)
        finalized = {
            "height": finalized_raw["height"],
            "block_hash": finalized_raw["block_hash"],
        }
    else:
        finalized = {
            "height": anchor["height"],
            "block_hash": anchor["block_hash"],
        }
    if not isinstance(steps, list) or not steps:
        raise _CheckpointError(ERR_STATE)
    validated_steps = []
    for raw in steps:
        if not isinstance(raw, dict):
            raise _CheckpointError(ERR_STATE)
        if v == 1:
            # Legacy steps carry only the linear-batch fields; they replay
            # as linear steps with no locator request.
            if tuple(raw.keys()) != HEADER_STEP_KEYS:
                raise _CheckpointError(ERR_STATE)
            kind = "linear"
            locators = None
        else:
            if tuple(raw.keys()) != HEADER_STEP_V2_KEYS:
                raise _CheckpointError(ERR_STATE)
            kind = raw["kind"]
            if kind not in HEADER_STEP_KINDS:
                raise _CheckpointError(ERR_STATE)
            locators = raw["locators"]
            if kind == "linear":
                # A linear step never carries a locator request.
                if locators is not None:
                    raise _CheckpointError(ERR_STATE)
            elif not isinstance(locators, list) or not locators:
                raise _CheckpointError(ERR_STATE)
        if not crypto.is_hex64(raw["tip_hash"]):
            raise _CheckpointError(ERR_STATE)
        if not isinstance(raw["trust"], dict):
            raise _CheckpointError(ERR_STATE)
        if not isinstance(raw["documents"], list) or not raw["documents"]:
            raise _CheckpointError(ERR_STATE)
        validated_steps.append(
            {
                "kind": kind,
                "tip_hash": raw["tip_hash"],
                "trust": raw["trust"],
                "documents": raw["documents"],
                "locators": locators,
            }
        )
    if not crypto.is_hex64(digest):
        raise _CheckpointError(ERR_STATE)

    return {
        "v": v,
        "generation": generation,
        "anchor": {key: anchor[key] for key in HEADER_ANCHOR_KEYS},
        "tip": {key: tip[key] for key in HEADER_TIP_KEYS},
        "finalized": finalized,
        "steps": validated_steps,
        "hash": digest,

"""Cryptographic helpers: Ed25519 verification, SHA-256 ids and Merkle roots."""
from __future__ import annotations

import hashlib
import hmac
import json
import re

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
    Ed25519PublicKey,
)


def canonical_message(sender: str, recipient: str, amount: int) -> bytes:
    """Deterministic byte representation of a transaction payload.

    The payload is serialized as compact JSON with sorted keys so the same
    (from, to, amount) triple always yields identical bytes on every client.
    """
    payload = {"amount": amount, "from": sender, "to": recipient}
    return json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def compute_tx_id(message: bytes) -> str:
    """SHA-256 hex digest of the canonical transaction message."""
    return sha256_hex(message)


def generate_private_key() -> str:
    """Generate a fresh Ed25519 private seed as 64 lowercase hex chars."""
    return Ed25519PrivateKey.generate().private_bytes(
        serialization.Encoding.Raw,
        serialization.PrivateFormat.Raw,
        serialization.NoEncryption(),
    ).hex()


def derive_public_key(private_key_hex: str) -> str | None:
    """Derive the 64-hex Ed25519 public key from a 64-hex private seed.

    Returns None for malformed hex or a wrong-length seed rather than raising,
    so callers can treat every malformed key uniformly as a 400.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return _public_hex(private_key)


def _public_hex(private_key: Ed25519PrivateKey) -> str:
    return private_key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


def sign_message(private_key_hex: str, message: bytes) -> str | None:
    """Sign ``message`` with an Ed25519 seed (64 hex chars); hex signature.

    Returns None for a malformed private key rather than raising.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return private_key.sign(message).hex()


def verify_signature(public_key_hex: str, message: bytes, signature_hex: str) -> bool:
    """Verify an Ed25519 signature (public key and signature are hex strings).

    Returns False for malformed hex or wrong key/signature lengths rather than
    raising, so callers can treat every verification failure uniformly.
    """
    try:
        public_bytes = bytes.fromhex(public_key_hex)
        signature_bytes = bytes.fromhex(signature_hex)
    except ValueError:
        return False
    if len(public_bytes) != 32 or len(signature_bytes) != 64:
        return False
    try:
        public_key = Ed25519PublicKey.from_public_bytes(public_bytes)
        public_key.verify(signature_bytes, message)
    except (InvalidSignature, ValueError):
        return False
    return True


# Merkle root of an empty transaction list; fixed so genesis blocks are identical.
EMPTY_MERKLE_ROOT = sha256_hex(b"")


def merkle_root(tx_ids: list[str]) -> str:
    """SHA-256 Merkle root of the given tx ids.

    Levels are built by hashing ``sha256(left + right)`` hex-string pairs;
    a lone odd node at a level is promoted by pairing it with itself.
    Callers normally pass ids already sorted ascending.
    """
    if not tx_ids:
        return EMPTY_MERKLE_ROOT
    level = list(tx_ids)
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
    return level[0]


# A SHA-256 digest rendered as 64 lowercase hexadecimal characters.
_HEX64_RE = re.compile(r"[0-9a-f]{64}")

# A 64-byte Ed25519 signature rendered as 128 lowercase hex characters.
_HEX128_RE = re.compile(r"[0-9a-f]{128}")

# Maximum Merkle depth we accept: 64 sibling levels already cover trees with up
# to 2**64 leaves, so a longer sibling path is necessarily malformed.
MAX_MERKLE_DEPTH = 64


def _is_hex64(value: object) -> bool:
    return isinstance(value, str) and _HEX64_RE.fullmatch(value) is not None


def is_hex64(value: object) -> bool:
    """True iff ``value`` is a 64-char lowercase SHA-256 hex string."""
    return _is_hex64(value)


def is_hex128(value: object) -> bool:
    """True iff ``value`` is a 128-char lowercase Ed25519 signature hex string."""
    return isinstance(value, str) and _HEX128_RE.fullmatch(value) is not None


def merkle_proof(tx_ids: list[str], index: int) -> list[dict]:
    """Sibling path from the leaf at ``index`` up to the Merkle root.

    Mirrors :func:`merkle_root`: levels hash ``sha256(left + right)`` hex pairs
    and a lone odd node is paired with itself. Each returned item has a
    ``direction`` ("left" or "right") recording which side the *sibling* sits
    on relative to the path node, and the sibling's ``hash``. Items are ordered
    from the leaf level toward the root. Raises ValueError for an empty list or
    an out-of-range index.
    """
    if not tx_ids:
        raise ValueError("cannot build a Merkle proof for an empty tree")
    if isinstance(index, bool) or not isinstance(index, int):
        raise ValueError("index must be an integer")
    if index < 0 or index >= len(tx_ids):
        raise ValueError("transaction index out of range")

    level = list(tx_ids)
    position = index
    siblings: list[dict] = []
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        if position % 2 == 0:
            # Path node is the left child; sibling sits on its right.
            siblings.append({"direction": "right", "hash": level[position + 1]})
        else:
            # Path node is the right child; sibling sits on its left.
            siblings.append({"direction": "left", "hash": level[position - 1]})
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
        position //= 2
    return siblings


def verify_merkle_proof(
    tx_id: str,
    siblings: list[dict],
    merkle_root: str,
    block_hash: str,
    expected_block_hash: str,
) -> bool:
    """Verify a Merkle proof and bind it to a specific block hash.

    Re-hashes the leaf (``tx_id``) with the sibling path from leaf to root and
    compares the result with ``merkle_root``; ``block_hash`` must additionally
    equal ``expected_block_hash``. Every malformed input (non-64-char lowercase
    hex hash, illegal direction, non-list path, excessive depth) and every
    mismatch returns False rather than raising.
    """
    try:
        if not _is_hex64(tx_id):
            return False
        if not _is_hex64(merkle_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_block_hash):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        current = tx_id
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            if direction == "left":
                pair = sibling_hash + current
            elif direction == "right":
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))

        if not hmac.compare_digest(current, merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# Exact, ordered key sets of a batch Merkle-proof response document. They let
# verify_merkle_proof_bundle reject missing/extra keys *and* a wrong key order.
_BUNDLE_TOP_KEYS = ("height", "block_hash", "merkle_root", "transaction_ids", "proofs")
_BUNDLE_PROOF_KEYS = ("tx_id", "index", "siblings")
_BUNDLE_SIBLING_KEYS = ("direction", "hash")


def _exact_keys(value: object, keys: tuple[str, ...]) -> bool:
    """True iff ``value`` is a dict with exactly ``keys``, in that insertion order."""
    return isinstance(value, dict) and tuple(value.keys()) == keys


def verify_merkle_proof_bundle(
    bundle: object,
    expected_block_hash: object,
    expected_merkle_root: object,
) -> bool:
    """Strictly verify a batch Merkle-proof bundle offline.

    The bundle mirrors POST /v1/blocks/{height}/proofs::

        {"height": H, "block_hash": B, "merkle_root": R,
         "transaction_ids": [id, ...],     # ALL block leaves, ascending
         "proofs": [{"tx_id", "index", "siblings"}, ...]}  # requested subset

    ``transaction_ids`` is the block's complete, ascending leaf list; ``proofs``
    covers the requested tx_ids (a subset of it), itself sorted by tx_id. Every
    proof's leaf-to-root sibling path is re-hashed with the same pairing rules
    as :func:`merkle_root` (``sha256(left + right)`` hex pairs, a lone odd node
    paired with itself); the root is additionally recomputed directly from
    ``transaction_ids`` and must equal both the bundle's ``merkle_root`` and
    ``expected_merkle_root``, while ``block_hash`` must equal
    ``expected_block_hash``. Each proof ``index`` must be the tx_id's exact
    position in ``transaction_ids`` and its path must agree with that index at
    every level.

    Every defect — a missing/extra key, a wrong key order, a wrong type, a
    non-boolean/negative height, a duplicate/non-hex/non-string/unsorted tx_id,
    an unknown or duplicated proof tx_id, an out-of-range index, a path
    inconsistent with the index (including the phantom self-pair slot), an
    illegal direction or hash, excessive depth, an empty proof list, a tampered
    leaf list/root or block hash — returns False rather than raising.
    """
    try:
        if not _exact_keys(bundle, _BUNDLE_TOP_KEYS):
            return False
        if not _is_hex64(expected_block_hash) or not _is_hex64(expected_merkle_root):
            return False
        height = bundle["height"]
        block_hash = bundle["block_hash"]
        bundle_root = bundle["merkle_root"]
        transaction_ids = bundle["transaction_ids"]
        proofs = bundle["proofs"]

        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            return False
        if not _is_hex64(block_hash):
            return False
        if not _is_hex64(bundle_root):
            return False
        if not isinstance(transaction_ids, list) or not transaction_ids:
            return False
        if not isinstance(proofs, list) or not proofs:
            return False
        if any(not _is_hex64(tx_id) for tx_id in transaction_ids):
            return False
        # Unique leaves ...
        if len(set(transaction_ids)) != len(transaction_ids):
            return False
        # ... in ascending tx_id order, matching the block's leaf ordering.
        if transaction_ids != sorted(transaction_ids):
            return False
        # The root is recomputed straight from the claimed leaf list, so the
        # list can never be tampered with independently of the paths.
        if not hmac.compare_digest(merkle_root(transaction_ids), bundle_root):
            return False

        positions = {tx_id: i for i, tx_id in enumerate(transaction_ids)}
        proof_ids: list[str] = []
        leaf_count = len(transaction_ids)
        for proof in proofs:
            if not _exact_keys(proof, _BUNDLE_PROOF_KEYS):
                return False
            tx_id = proof["tx_id"]
            index = proof["index"]
            siblings = proof["siblings"]
            if not _is_hex64(tx_id) or tx_id not in positions:
                return False
            if tx_id in proof_ids:
                return False
            if isinstance(index, bool) or not isinstance(index, int):
                return False
            # The index must be exactly the tx_id's leaf position; anything
            # else is a mismatch or out of range regardless of supplied hashes.
            if index != positions[tx_id] or not 0 <= index < leaf_count:
                return False
            if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
                return False

            # A depth-D path addresses one of 2**D leaf slots.
            depth = len(siblings)
            if index >= (1 << depth):
                return False
            current = tx_id
            position = index
            for item in siblings:
                if not _exact_keys(item, _BUNDLE_SIBLING_KEYS):
                    return False
                direction = item["direction"]
                sibling_hash = item["hash"]
                if not _is_hex64(sibling_hash):
                    return False
                # The odd-node promotion pairs the last (even-positioned) node
                # with a copy of itself, so a genuine self-pair always points
                # at a right sibling. A left sibling equal to the current node
                # addresses the phantom duplicate slot, which is never a real
                # leaf. The path must also agree with the index at every
                # level: an even position is the left child (sibling on its
                # right), an odd position the right child.
                if direction == "left":
                    if position % 2 == 0 or sibling_hash == current:
                        return False
                    pair = sibling_hash + current
                elif direction == "right":
                    if position % 2 == 1:
                        return False
                    pair = current + sibling_hash
                else:
                    return False
                current = sha256_hex(pair.encode("ascii"))
                position //= 2

            if not hmac.compare_digest(current, bundle_root):
                return False
            proof_ids.append(tx_id)

        # Proofs must be unique and ordered by tx_id ascending.
        if proof_ids != sorted(proof_ids):
            return False

        if not hmac.compare_digest(bundle_root, expected_merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# -- account state Merkle tree ----------------------------------------------


def account_state_leaf(
    account: str, balance: int, confirmed_transactions: list[str]
) -> str:
    """SHA-256 leaf of one account's confirmed state.

    The leaf is ``sha256(utf8(JSON))`` of the canonical compact JSON document
    ``{"account":a,"balance":b,"confirmed_transactions":T}`` serialized with
    ``sort_keys=True``, ``ensure_ascii=False`` and ``separators=(",",":")``.
    ``T`` keeps its original (on-chain) order; ``sort_keys`` only orders the
    three top-level keys.
    """
    document = {
        "account": account,
        "balance": balance,
        "confirmed_transactions": confirmed_transactions,
    }
    raw = json.dumps(
        document, sort_keys=True, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    return sha256_hex(raw)


def account_state_root(leaves: list[str]) -> str:
    """Merkle root of account-state leaves ordered by ascending account.

    Uses the same pairing rules as :func:`merkle_root` (hex-string pairs
    hashed ``sha256(left + right)``, a lone odd node paired with itself); an
    empty account set has the same root as an empty tx list.
    """
    return merkle_root(leaves)


def verify_account_proof(
    proof: object,
    expected_root: object,
    expected_height: object,
    expected_hash: object,
) -> bool:
    """Verify an account-state Merkle proof offline.

    Recomputes the account leaf from
    ``{account, balance, confirmed_transactions}``, walks the leaf-to-root
    ``siblings`` path, and requires the recomputed root to equal both the
    proof's ``state_root`` and ``expected_root``, while ``height`` /
    ``block_hash`` anchor the tree to the expected confirmed tip. Every
    malformed input — a non-64-char lowercase hex hash or anchor, an illegal
    direction, an illegal index, a malformed leaf/balance/transaction list, a
    path inconsistent with the index, excessive depth — returns False rather
    than raising.
    """
    try:
        if not isinstance(proof, dict):
            return False
        account = proof.get("account")
        balance = proof.get("balance")
        transactions = proof.get("confirmed_transactions")
        index = proof.get("index")
        state_root = proof.get("state_root")
        height = proof.get("height")
        block_hash = proof.get("block_hash")
        siblings = proof.get("siblings")

        if not isinstance(account, str) or not account:
            return False
        if isinstance(balance, bool) or not isinstance(balance, int) or balance < 0:
            return False
        if not isinstance(transactions, list):
            return False
        if any(not _is_hex64(tx_id) for tx_id in transactions):
            return False
        if isinstance(index, bool) or not isinstance(index, int) or index < 0:
            return False
        if not isinstance(height, bool) and isinstance(height, int):
            if height < 0:
                return False
        else:
            return False
        if not _is_hex64(state_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_hash):
            return False
        if not _is_hex64(expected_root):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        # The leaf is always recomputed from the proof's own triple; a
        # client-supplied leaf value is never trusted.
        depth = len(siblings)
        # A depth-D path addresses one of 2**D leaf slots; a single-leaf tree
        # (D == 0) can only ever be index 0. An index outside that range is
        # illegal regardless of any hashes the caller supplies.
        if index >= (1 << depth):
            return False
        current = account_state_leaf(account, balance, transactions)
        position = index
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            # The odd-node promotion pairs the last (even-positioned) node
            # with a copy of itself, so a genuine self-pair always points at a
            # right sibling. A left sibling equal to the current node addresses
            # the phantom duplicate slot, which is never a real account.
            if direction == "left" and sibling_hash == current:
                return False
            # The path must agree with the index: at every level an even
            # position is the left child (sibling on its right) and an odd
            # position the right child.
            if direction == "left":
                if position % 2 == 0:
                    return False
                pair = sibling_hash + current
            elif direction == "right":
                if position % 2 == 1:
                    return False
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))
            position //= 2

        if not hmac.compare_digest(current, state_root):
            return False
        if not hmac.compare_digest(current, expected_root):
            return False
        if height != expected_height:
            return False
        if not hmac.compare_digest(block_hash, expected_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False

def get_trust_document(self) -> tuple[int, dict]:
    """GET /v1/trust — the offline light-client verify document.

    ``genesis_hash`` always pins the fixed canonical genesis block;
    ``sources`` contains only active, unexpired entries in the light
    client's shape ``{public_key, expires_at}``; the keyless
    ``allowlist`` is preserved verbatim; ``audit_signers`` lists every
    checkpoint key ever held in ascending version order as
    ``{version, public_key, activated_event_id}`` (version 1 is activated
    at event 0), so offline audit export verification can pick the key
    that signed each checkpoint; ``source_key_history`` maps every
    registered source to every source key it ever held, in ascending
    version order as ``{version, public_key, activated_event_id}``
    (version 1 is activated at the ``source_registered`` event, each
    rotation at its ``source_rotated`` event; revocation retains the full
    history), so offline attested-range verification can pick the key that
    signed an older attestation.
    """
    with self.store.lock:
        now = time.time()
        sources = {}
        for source, rec in self.store.trust_sources.items():
            if rec["status"] != TRUST_ACTIVE or rec["expires_at"] <= now:
                continue
            sources[source] = {
                "public_key": rec["public_key"],
                "expires_at": rec["expires_at"],
            }
        audit_signers = [dict(entry) for entry in self.store.audit_signer_history]
        source_key_history = {
            source: [dict(entry) for entry in history]
            for source, history in self.store.source_key_history.items()
        }
        return 200, {
            "genesis_hash": self.store.chain[0].block_hash,
            "sources": sources,
            "allowlist": dict(self.store.allowlist),
            "audit_signers": audit_signers,
            "source_key_history": source_key_history,
        }

# -- keyless allowlist management -----------------------------------------

@staticmethod
def _allowlist_entry(source: str, expires_at: int) -> dict:
    """Public shape of one keyless allowlist entry."""
    return {"source": source, "expires_at": expires_at}

def add_allowlist_entry(self, payload: object) -> tuple[int, dict]:
    """POST /v1/trust/allowlist — add a keyless source for offline verify.

    The body carries ``source`` (a non-empty string) and ``expires_at`` (a
    plain, non-boolean Unix-seconds integer); anything malformed is 400. A
    new entry is persisted together with its ``allowlist_added`` audit
    event in one atomic write and returns 201 with
    ``{source, expires_at}``. Re-posting the exact same content is
    idempotent (200, no new event, no write); the same source with a
    different expiry conflicts 409 (remove it first).

    The allowlist is keyless and offline-only: it never creates a trust
    source and never authorizes POST /v1/forks/sync, and expired entries
    are retained verbatim (an expired entry is still an entry, so a
    same-content retry stays 200 and a changed-content retry stays 409).
    """
    if not isinstance(payload, dict):
        return 400, {"error": "request body must be a JSON object"}
    for field in ("source", "expires_at"):
        if field not in payload:
            return 400, {"error": f"missing field: {field}"}
    source = payload["source"]
    expires_at = payload["expires_at"]
    if not isinstance(source, str) or not source:
        return 400, {"error": "field 'source' must be a non-empty string"}
    # bool is a subclass of int: reject it and every other non-int type.
    if isinstance(expires_at, bool) or not isinstance(expires_at, int):
        return 400, {"error": "field 'expires_at' must be a Unix-seconds integer"}
    with self.store.lock:
        existing = self.store.allowlist.get(source)
        if existing is not None:
            if existing == expires_at:
                # Idempotent re-add: the stored entry is reported
                # unchanged, with no new audit event and no new write.
                return 200, self._allowlist_entry(source, existing)
            return 409, {"error": "allowlist entry already exists with different content"}
        self.store.allowlist[source] = expires_at
        self.store.append_audit_event(
            EVENT_ALLOWLIST_ADDED,
            {"source": source, "expires_at": expires_at},
        )
        try:
            self.store.save()
        except BaseException:
            # Undo the entry and its event together so a failed write
            # never leaves one without the other.
            self.store.allowlist.pop(source, None)
            self.store.truncate_audit_events(1)
            raise
        return 201, self._allowlist_entry(source, expires_at)

def remove_allowlist_entry(self, source: object) -> tuple[int, dict]:
    """DELETE /v1/trust/allowlist/{source} — remove a keyless entry.

    An unknown source (including the empty path segment) returns 404. A
    known entry is deleted and its ``allowlist_removed`` event (carrying
    the source and the removed entry's ``expires_at``) is persisted in the
    same atomic write; a failed write restores both. Returns
    ``{source, removed: true}`` on success. Removing an allowlist entry
    never touches a same-named entry of the persistent trust registry.
    """
    if not isinstance(source, str) or not source:
        return 404, {"error": "unknown allowlist entry"}
    with self.store.lock:
        existing = self.store.allowlist.get(source)
        if existing is None:
            return 404, {"error": "unknown allowlist entry"}
        del self.store.allowlist[source]
        self.store.append_audit_event(
            EVENT_ALLOWLIST_REMOVED,
            {"source": source, "expires_at": existing},
        )

    for tx in self.store.pending.values():
        if tx.sender == account:
            balance -= tx.amount
    return balance

# -- fork candidates -----------------------------------------------------

@staticmethod
def _fork_summary(blocks: list) -> dict:
    """Public fork descriptor S: tip_hash, height, length, status."""
    tip = blocks[-1]
    return {
        "tip_hash": tip.block_hash,
        "height": tip.height,
        # The length counts every block including the genesis block.
        "length": len(blocks),
        "status": tip.status,
    }

def _winning_fork(self) -> tuple[str, list]:
    """Pick the winner among the canonical chain and every candidate.

    Longest chain wins; equal lengths are broken by the smallest tip hash
    (lexicographic hex order). Returns (tip_hash, block list).
    """
    contenders: list[tuple[str, list]] = [
        (self.store.tip_hash(), self.store.chain)
    ]
    contenders.extend(self.store.forks.items())
    contenders.sort(key=lambda item: (-len(item[1]), item[0]))
    return contenders[0]

def submit_fork_candidate(self, payload: object) -> tuple[int, dict]:
    """POST /v1/forks/candidates — validate and store a candidate fork.

    Returns 201 with the fork descriptor S. Malformed or invalid forks
    return 400; a fork already known (identical to the canonical tip or an
    existing candidate tip) returns 409.
    """
    if not isinstance(payload, dict):
        return 400, {"error": "request body must be a JSON object"}
    blocks_raw = payload.get("blocks")
    if not isinstance(blocks_raw, list):
        return 400, {"error": "missing field: blocks (must be a list)"}
    try:
        fork = self.store.validate_fork_blocks(blocks_raw)
    except ValueError as exc:
        return 400, {"error": str(exc)}
    summary = self._fork_summary(fork)
    # An exported fork (the five-field {tip_hash, height, length, status,
    # blocks} document) may be resubmitted verbatim; every supplied summary
    # field is re-verified against the recomputed descriptor.
    for field in ("tip_hash", "height", "length", "status"):
        if field in payload and payload[field] != summary[field]:
            return 400, {"error": f"summary field {field!r} does not match the blocks"}
    tip_hash = fork[-1].block_hash
    with self.store.lock:
        self._prune_expired_syncs()
        # A tip hash equal to any canonical block hash means the candidate
        # is exactly the canonical chain or a prefix of it (the block hash
        # binds height, parent and Merkle root), so it carries nothing new.
        if any(tip_hash == block.block_hash for block in self.store.chain):
            return 409, {"error": "fork is identical to the canonical chain"}
        if tip_hash in self.store.forks:
            return 409, {"error": "candidate fork already exists", "tip_hash": tip_hash}
        self.store.forks[tip_hash] = fork
        try:
            self.store.save()
        except BaseException:
            self.store.forks.pop(tip_hash, None)
            raise
    return 201, self._fork_summary(fork)

def get_chain(self) -> tuple[int, dict]:
    """GET /v1/chain — canonical chain, candidates sorted by tip hash and
    the adoptable winner (a non-canonical chain that beats canonical).
    """
    with self.store.lock:
        self._prune_expired_syncs()
        canonical = self._fork_summary(self.store.chain)

# atomic replace) across threads within one process.
_checkpoint_locks: dict[str, threading.RLock] = {}
_checkpoint_locks_guard = threading.Lock()


def _checkpoint_lock(path: str) -> threading.RLock:
    key = os.path.abspath(path)
    with _checkpoint_locks_guard:
        lock = _checkpoint_locks.get(key)
        if lock is None:
            lock = threading.RLock()
            _checkpoint_locks[key] = lock
        return lock


def _canonical_json_bytes(value: object) -> bytes:
    """Sorted-key, compact, unescaped-non-ASCII UTF-8 canonical JSON bytes."""
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def _checkpoint_state_hash(generation: int, anchor: dict, tip: dict, context: dict) -> str:
    """SHA-256 over the canonical JSON bytes of every field but state_hash."""
    body = {
        "generation": generation,
        "anchor": anchor,
        "tip": tip,
        "context": context,
    }
    return hashlib.sha256(_canonical_json_bytes(body)).hexdigest()


def _failed_advance(category: str) -> dict:
    return {"ok": False, "error": category}


def advance(
    path: str,
    docs: object,
    trust: object,
    anchor: object,
    now: object,
) -> dict:
    """Verify a range-export batch and durably checkpoint it at ``path``.

    ``docs`` is an ordered, non-empty batch of range deliveries verified with
    :func:`verify_range_exports` against ``trust`` and ``anchor`` at time
    ``now``: ``now`` must be a plain (non-boolean) non-negative integer; the
    first use of ``path`` requires a legal ``anchor`` (``{height, block_hash}``),
    while a later advance passes ``None`` (continue from the stored tip) or the
    stored tip's ``{height, block_hash}``.

    On success the checkpoint is written atomically (a uniquely named temp file
    in the same directory, fsynced and ``os.replace``d under a per-path lock)
    with key order ``generation, anchor, tip, context, state_hash``; generation
    starts at 1 and increments once per successful advance, so a failed
    verification never bumps it. The return value is the verifier result with
    the new ``generation`` appended as the final key.

    The same transaction appends the new checkpoint to the generation-history
    sidecar at ``path + ".history"`` (see the module docstring for the exact
    format): a missing sidecar is opened at ``base = {0, Z}`` for a first
    advance, or migrated from a pre-existing generation-``g`` checkpoint as
    ``base = {g-1, Z}`` with that checkpoint as the first record; an existing
    sidecar is strictly reloaded and replayed, and its last record must
    reproduce the stored checkpoint. Both files are written under the shared
    per-path lock; an ``io`` failure restores the original bytes of both
    best-effort (crash atomicity across the pair is not guaranteed).

    Every failure is ``{"ok": False, "error": category}`` with category one of
    ``input`` (bad arguments or checkpoint shape), ``auth``/``expired``/
    ``integrity`` (batch verification), ``state`` (an existing checkpoint or
    sidecar fails its key-order/type/hash/replay checks; it is never truncated
    or rebuilt) and ``io`` (the checkpoint cannot be read or written).
    """
    # Argument shape is validated before any file or verification work.
    if not isinstance(path, str) or not path:
        return _failed_advance(ERR_INPUT)
    if not _is_int(now) or now < 0:
        return _failed_advance(ERR_INPUT)

    lock = _checkpoint_lock(path)
    with lock:
        try:
            previous = _load_checkpoint(path)
            sidecar = _load_history(_history_path(path))
        except _CheckpointError as failure:
            return _failed_advance(failure.category)

        if previous is None:
            # A sidecar without its checkpoint is unrecoverable corruption.
            if sidecar is not None:
                return _failed_advance(ERR_STATE)
            # First use: the caller must pin a legal anchor.
            expected_anchor = _validate_advance_anchor(anchor)
            if expected_anchor is None:
                return _failed_advance(ERR_INPUT)
            generation = 0
            base = {"generation": 0, "hash": HISTORY_ZERO_HASH}
            records: list[dict] = []
        else:
            generation = previous["generation"]
            stored_tip = previous["tip"]
            if anchor is None:
                # Continue the continuous chain from the stored closed tip.
                expected_anchor = {
                    "height": stored_tip["height"],
                    "block_hash": stored_tip["tip_hash"],
                }
            else:
                expected_anchor = _validate_advance_anchor(anchor)
                if (
                    expected_anchor is None
                    or expected_anchor
                    != {
                        "height": stored_tip["height"],
                        "block_hash": stored_tip["tip_hash"],
                    }
                ):

"""Data models for transactions and blocks."""
from __future__ import annotations

import json
from dataclasses import dataclass

from . import crypto

# Block lifecycle states for the confirm/rollback state machine.
STATUS_PENDING = "pending"
STATUS_CONFIRMED = "confirmed"
BLOCK_STATUSES = (STATUS_PENDING, STATUS_CONFIRMED)


@dataclass
class Transaction:
    sender: str
    recipient: str
    amount: int
    signature: str

    @property
    def message(self) -> bytes:
        return crypto.canonical_message(self.sender, self.recipient, self.amount)

    @property
    def tx_id(self) -> str:
        return crypto.compute_tx_id(self.message)

    def to_dict(self) -> dict:
        """JSON-safe representation used both for storage and API output."""
        return {
            "from": self.sender,
            "to": self.recipient,
            "amount": self.amount,
            "signature": self.signature,
            "tx_id": self.tx_id,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Transaction":
        # The raw JSON value is validated BEFORE any use: no int()/str()
        # coercion, so a string, float or boolean amount can never masquerade
        # as the integer it converts to. bool is an int subclass and must be
        # rejected explicitly.
        amount = data["amount"]
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError("transaction amount must be an integer")
        return cls(
            sender=data["from"],
            recipient=data["to"],
            amount=amount,
            signature=data["signature"],
        )


def block_header_bytes(height: int, prev_hash: str, merkle: str) -> bytes:
    """Deterministic serialization of the fields covered by the block hash.

    No timestamp is included: a block with the same parent and the same ordered
    transactions must always hash identically.
    """
    header = {"height": height, "merkle_root": merkle, "prev_hash": prev_hash}
    return json.dumps(header, sort_keys=True, separators=(",", ":")).encode("utf-8")


def compute_block_hash(height: int, prev_hash: str, merkle: str) -> str:
    return crypto.sha256_hex(block_header_bytes(height, prev_hash, merkle))


@dataclass
class Block:
    height: int
    prev_hash: str
    merkle_root: str
    transactions: list[Transaction]
    block_hash: str
    status: str = STATUS_CONFIRMED

    @classmethod
    def create(
        cls,
        height: int,
        prev_hash: str,
        transactions: list[Transaction],
        status: str = STATUS_CONFIRMED,
    ) -> "Block":
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        ordered = sorted(transactions, key=lambda tx: tx.tx_id)
        merkle = crypto.merkle_root([tx.tx_id for tx in ordered])
        block_hash = compute_block_hash(height, prev_hash, merkle)
        return cls(
            height=height,
            prev_hash=prev_hash,
            merkle_root=merkle,
            transactions=ordered,
            block_hash=block_hash,
            status=status,
        )

    def to_dict(self) -> dict:
        return {
            "height": self.height,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "block_hash": self.block_hash,
            "status": self.status,
            "transactions": [tx.to_dict() for tx in self.transactions],
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Block":
        # State files written before the status machine existed have no
        # "status" key; every block in such a file was final, so they load
        # as confirmed. This compatibility default never extends to numeric
        # coercion: the raw height must already be a non-boolean,
        # non-negative integer — a string, float or bool is rejected, never
        # converted.
        status = data.get("status", STATUS_CONFIRMED)
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        height = data["height"]
        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            raise ValueError("block height must be a non-negative integer")
        transactions = data["transactions"]
        if not isinstance(transactions, list):
            raise ValueError("block transactions must be a list")
        return cls(
            height=height,
            prev_hash=data["prev_hash"],
            merkle_root=data["merkle_root"],
            block_hash=data["block_hash"],
            transactions=[Transaction.from_dict(t) for t in transactions],
            status=status,
        )

    def to_summary(self) -> dict:
        """Response shape for GET /v1/blocks/{height}."""
        return {
            "height": self.height,
            "block_hash": self.block_hash,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "status": self.status,
            "transaction_ids": [tx.tx_id for tx in self.transactions],
        }

# -- chain helpers --------------------------------------------------------

def tip(self) -> Block:
    return self.chain[-1]

def tip_hash(self) -> str:
    return self.chain[-1].block_hash

def next_height(self) -> int:
    return self.chain[-1].height + 1

def tip_is_pending(self) -> bool:
    return self.chain[-1].status == STATUS_PENDING

def block_at(self, height: int) -> Block | None:
    if 0 <= height < len(self.chain) and self.chain[height].height == height:
        return self.chain[height]
    return None

def rollback_tip(self) -> Block:
    """Remove the pending tip block and return its transactions to the mempool.

    Transactions are restored de-duplicated: an id already present in the
    pending set (resubmitted while the block was unconfirmed) is kept as
    is, not overwritten. Caller must hold the lock and must have checked
    that the tip is a pending block. Does not save; callers persist.
    """
    block = self.chain.pop()
    for tx in block.transactions:
        self.pending.setdefault(tx.tx_id, tx)

def _serialize_document(ordered: dict) -> bytes:
    """Compact UTF-8 JSON (non-ASCII unescaped) with one trailing newline."""
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _atomic_write_checkpoint(path: str, checkpoint: dict) -> None:
    """Write the checkpoint in declared key order and atomically replace ``path``."""
    ordered = {key: checkpoint[key] for key in CHECKPOINT_KEYS}
    _atomic_write_bytes(path, _serialize_document(ordered))


def _atomic_write_bytes(path: str, payload: bytes) -> None:
    """Atomically replace ``path`` with ``payload``.

    The temp file is fsynced before the replace and the directory afterwards,
    mirroring the main store's durability rules.
    """
    directory = os.path.dirname(os.path.abspath(path)) or "."
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(prefix=".light-checkpoint-", dir=directory)
    promoted = False
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(payload)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp_path, path)
        promoted = True
        _fsync_dir(directory)
    finally:
        if not promoted and os.path.exists(tmp_path):
            try:
                os.unlink(tmp_path)
            except OSError:
                pass


def _read_bytes_or_none(path: str) -> bytes | None:
    """Raw bytes of ``path`` (None when absent); other read errors propagate."""
    try:
        with open(path, "rb") as fh:
            return fh.read()
    except FileNotFoundError:
        return None


def _restore_bytes(path: str, original: bytes | None) -> None:
    """Best-effort compensation: put ``original`` back at ``path``.

    A file that did not exist is unlinked again. Any failure is swallowed —
    the caller already reports ``io`` and the next strict load surfaces the
    corruption as ``state``.
    """
    try:
        if original is None:
            os.unlink(path)
        else:
            _atomic_write_bytes(path, original)
    except OSError:
        pass


def _fsync_dir(directory: str) -> None:
    """Best-effort directory fsync so the checkpoint rename survives a crash."""
    try:
        dir_fd = os.open(directory, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    except OSError:
        return

